<?php
 namespace Dicom; class Net { const LOG = 'dicomNetExecute'; public $aet; public $aec; public $peer; public $port; public $incomingPort; public $out; public $exitcode; function __construct ($aet = null, $aec = null, $peer = null, $port = null, $incomingPort = 104) { $this->aet = $aet; $this->aec = $aec; $this->peer = $peer; $this->port = $port; $this->incomingPort = $incomingPort; } public function echoScu () { return $this->execute(BIN_ECHOSCU . $this->getParamsStr()); } public function findScu ($query, $queryModel, $maxResponses = null) { $queryModel = strtolower($queryModel); $keys = $query->commandKeys(); $params = $this->getParamsStr(); $res = false; if ($this->execute(BIN_FINDSCU . " --{$queryModel}{$keys}{$params}")) { $res = []; $dataSets = safe_explode('I: # Dicom-Data-Set', $this->out); for ($i = 1; $i < count($dataSets); ++$i) { $dcm = new Dcm; $dcm->setElements($dataSets[$i]); $res[] = $dcm; if (isset($maxResponses) && $i >= $maxResponses) { break; } } } return $res; } public function getScu ($query, $queryModel, $directory) { $queryModel = strtolower($queryModel); $keys = $query->commandKeys(); $params = $this->getParamsStr(); return $this->execute(BIN_GETSCU . " -od \"{$directory}\" --{$queryModel}{$keys}{$params}"); } public function moveScu ($query, $queryModel, $directory) { $queryModel = strtolower($queryModel); $keys = $query->commandKeys(); if ($this->aet) $keys .= " -aem \"{$this->aet}\""; if ($this->incomingPort) $keys .= " --port {$this->incomingPort}"; $params = $this->getParamsStr(); return $this->execute(BIN_MOVESCU . " -od \"{$directory}\" --{$queryModel}{$keys}{$params}"); } public function storeScu ($dcmfiles, $isDir = false, $wildcards = null) { $params = $this->getParamsStr(); if ($isDir) { $params .= " +sd"; if ($wildcards) { $params .= " +sp \"$wildcards\""; } } return $this->execute(BIN_STORESCU . "{$params} {$dcmfiles}"); } public function moveObjects ($fromNet, $query, $queryModel, $method) { $log = new \Log(self::LOG); $log->begin('--> Начало перемещение файлов'); $tempDir = realpath(sys_get_temp_dir()); $query->setElements([ '0008,0018' => null, '0008,0060' => null, '0010,0020' => null, '0020,000d' => null, '0020,000e' => null ], true); $objects = $fromNet->findScu($query, $queryModel); $log->info('К перемещению файлов ' . count($objects)); $query = new \Dicom\Item(['0008,0052' => 'IMAGE']); $count = 0; foreach ($objects as $object) { $uid = $object->get('0008,0018')->scalarValue(); $modality = $object->get('0008,0060')->scalarValue(); $log->info("Загрузка [{$modality}.{$uid}]..."); $query->set('0010,0020', $object->get('0010,0020')->scalarValue()); $query->set('0020,000d', $object->get('0020,000d')->scalarValue()); $query->set('0020,000e', $object->get('0020,000e')->scalarValue()); $query->set('0008,0018', $uid); if ($method === 'move') { if (!$fromNet->moveScu($query, $queryModel, $tempDir)) { $log->error('Ошибка загрузки (C-MOVE):')->text($fromNet->out); continue; } } else { if (!$fromNet->getScu($query, $queryModel, $tempDir)) { $log->error('Ошибка загрузки (C-GET):')->text($fromNet->out); continue; } } $log->time("ОК"); $files = glob("$tempDir/???.$uid"); if (empty($files)) { $log->error("Временный файл объекта не найден $tempDir/???.$uid"); continue; } $fileName = $files[0]; try { $fileSize = filesize($fileName); $fileSize = humanFileSize($fileSize); $log->info("Сохранение $fileName ($fileSize)..."); if (!$this->storeScu($fileName)) { $log->error('Ошибка передачи:')->text($this->out); continue; } $log->time("ОК"); $count++; } finally { $log->info("Удаление временного файла...", false); if (unlink($fileName) === false) { $log->error("Ошибка удаления временного файла $fileName"); } else { $log->add("ОК"); } } } $log->end('Окончание перемещения файлов'); return $count; } protected function getParamsStr () { $result = ""; if ($this->aet) $result .= " -aet \"{$this->aet}\""; if ($this->aec) $result .= " -aec \"{$this->aec}\""; $result .= " {$this->peer} {$this->port}"; return $result; } protected function execute ($command) { static $log; if (!isset($log)) { $log = new \Log(self::LOG); } $log->info($command); error_log($command); $this->out = executeCmd($command, $this->exitcode); $log->time("[exitcode = $this->exitcode]"); $logLevel = substr($this->out, 0, 2); return $this->exitcode === 0 && $logLevel !== 'E:' && $logLevel !== 'F:'; } } 